const API="https://api.telegram.org/bot", NL=String.fromCharCode(10);
const DEFAULT={};
const json=(x,s=200)=>new Response(JSON.stringify(x),{status:s,headers:{"content-type":"application/json; charset=utf-8"}});
const gk=(c)=>"group:"+c;
async function tg(e,m,p){const r=await fetch(API+e.BOT_TOKEN+"/"+m,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(p)});const d=await r.json();if(!d.ok)throw Error(d.description||m+" failed");return d.result}
async function gs(e){let x=await e.STORE.get("settings");try{return x?{...DEFAULT,...JSON.parse(x)}:{...DEFAULT}}catch{return {...DEFAULT}}}
async function ss(e,x){await e.STORE.put("settings",JSON.stringify(x))}
const groupCache=new Map();
async function group(e,id){const key=String(id),cached=groupCache.get(key),now=Date.now();if(cached&&now-cached.at<5000)return {...cached.value};let raw=await e.STORE.get(gk(id));const d={links:false,antispam:true,media:false,forwards:false,welcome:true,welcomeText:"خوش اومدی {name} 👋",rules:"هنوز قانونی ثبت نشده.",badWords:[],messages:0,deleted:0,warned:0,warnLimit:3,repeatSpam:true,contentGuard:true};let value;try{value=raw?{...d,...JSON.parse(raw)}:d}catch{value=d}if(groupCache.size>=500){const first=groupCache.keys().next().value;groupCache.delete(first)}groupCache.set(key,{at:now,value});return {...value}}
async function sg(e,id,x){await e.STORE.put(gk(id),JSON.stringify(x));groupCache.set(String(id),{at:Date.now(),value:{...x}})}
const owner=(u,e)=>u&&String(u.id)===String(e.OWNER_ID);
function panelText(){return "╭━━━〔 ✦ FXI CONTROL ✦ 〕━━━╮"+NL+"┃ مرکز فرماندهی و مدیریت"+NL+"┃ ابزارهای شخصی • مدیریت گروه"+NL+"┃ نسخه 5.3.0"+NL+"╰━━━━━━━━━━━━━━━━━━━━━━╯"+NL+NL+"✨ بخش موردنظرت را انتخاب کن.\nتمام تنظیمات از همین پنل در دسترس است."}
function keyboard(){return {inline_keyboard:[[{text:"👥 مدیریت گروه‌ها",callback_data:"groups"}],[{text:"✨ قابلیت‌های ربات",callback_data:"features"}],[{text:"📊 آمار و گزارش",callback_data:"stats"},{text:"📚 راهنمای کامل",callback_data:"help"}],[{text:"🔄 بروزرسانی پنل",callback_data:"home"}]]}}
async function panel(e,id){const s=await gs(e);await tg(e,"sendMessage",{chat_id:id,text:panelText(),reply_markup:keyboard()})}
function userModerationKeyboard(id,userId){return {inline_keyboard:[[{text:"⚠️ اخطار",callback_data:"um:"+id+":"+userId+":warn"},{text:"🔇 سکوت ۱۰ دقیقه",callback_data:"um:"+id+":"+userId+":mute"}],[{text:"🔊 رفع سکوت",callback_data:"um:"+id+":"+userId+":unmute"}],[{text:"🚪 اخراج",callback_data:"um:"+id+":"+userId+":kick"},{text:"⛔ مسدودسازی",callback_data:"um:"+id+":"+userId+":ban"}],[{text:"✖️ بستن",callback_data:"um:"+id+":"+userId+":close"}]]}}
function groupQuickKeyboard(id,x){return {inline_keyboard:[[{text:x.links?"🔓 قفل لینک خاموش":"🔒 قفل لینک روشن",callback_data:"gm:"+id+":links"},{text:x.antispam?"🛡 ضداسپم خاموش":"🛡 ضداسپم روشن",callback_data:"gm:"+id+":spam"}],[{text:x.welcome?"👋 خوشامد خاموش":"👋 خوشامد روشن",callback_data:"gm:"+id+":welcome"},{text:x.media?"🖼 آزادسازی رسانه":"🖼 قفل رسانه",callback_data:"gm:"+id+":media"}],[{text:x.forwards?"🚫 ضد فوروارد خاموش":"🚫 ضد فوروارد روشن",callback_data:"gm:"+id+":forwards"},{text:x.repeatSpam===false?"🔁 تکرار پیام روشن":"🔁 تکرار پیام خاموش",callback_data:"gm:"+id+":repeat"}],[{text:x.contentGuard===false?"🧹 فیلتر متن شلوغ روشن":"🧹 فیلتر متن شلوغ خاموش",callback_data:"gm:"+id+":contentguard"}],[{text:"📜 مشاهده قوانین",callback_data:"gm:"+id+":rules"},{text:"📊 آمار گروه",callback_data:"gm:"+id+":stats"}]]}}
async function groupQuickPanel(e,id,chatId,messageId){const x=await group(e,id),text="⚙️ پنل سریع مدیریت گروه\n\nبا دکمه‌های زیر تنظیمات را مستقیم تغییر بده.\nقفل لینک: "+(x.links?"روشن":"خاموش")+" | ضداسپم: "+(x.antispam?"روشن":"خاموش")+"\nخوشامدگویی: "+(x.welcome?"روشن":"خاموش")+" | رسانه: "+(x.media?"قفل":"آزاد")+"\nفوروارد: "+(x.forwards?"محدود":"آزاد")+" | پیام تکراری: "+(x.repeatSpam===false?"خاموش":"روشن")+"\nفیلتر متن شلوغ: "+(x.contentGuard===false?"خاموش":"روشن");if(messageId)await tg(e,"editMessageText",{chat_id:chatId,message_id:messageId,text,reply_markup:groupQuickKeyboard(id,x)});else await tg(e,"sendMessage",{chat_id:chatId,text,reply_markup:groupQuickKeyboard(id,x)})}
async function callback(e,q){const d=q.data||"",chat=q.message.chat.id,mid=q.message.message_id;if(d.startsWith("um:")){const p=d.split(":"),id=p[1],targetId=p[2],action=p[3];if(!/^-?\d+$/.test(id)||!/^\d+$/.test(targetId)||String(chat)!==String(id)){await tg(e,"answerCallbackQuery",{callback_query_id:q.id,text:"درخواست نامعتبر"});return}const actor=await tg(e,"getChatMember",{chat_id:id,user_id:q.from.id}).catch(()=>null);if(!actor||!["administrator","creator"].includes(actor.status)){await tg(e,"answerCallbackQuery",{callback_query_id:q.id,text:"فقط مدیران گروه دسترسی دارند"});return}if(action==="close"){await tg(e,"answerCallbackQuery",{callback_query_id:q.id});await tg(e,"editMessageText",{chat_id:chat,message_id:mid,text:"پنل مدیریت عضو بسته شد."});return}const target=await tg(e,"getChatMember",{chat_id:id,user_id:Number(targetId)}).catch(()=>null);if(target&&["administrator","creator"].includes(target.status)){await tg(e,"answerCallbackQuery",{callback_query_id:q.id,text:"مدیر گروه قابل مدیریت نیست"});return}if(action==="back"){await tg(e,"answerCallbackQuery",{callback_query_id:q.id});await tg(e,"editMessageText",{chat_id:chat,message_id:mid,text:"👤 پنل مدیریت عضو\nشناسه: "+targetId+"\nعملیات موردنظر را انتخاب کن:",reply_markup:userModerationKeyboard(id,targetId)});return}if(action==="warn"){const x=await group(e,id);await warn(e,id,Number(targetId),x,"اخطار از پنل مدیریت");await tg(e,"answerCallbackQuery",{callback_query_id:q.id,text:"اخطار ثبت شد"});return}if(action==="mute"){await tg(e,"restrictChatMember",{chat_id:id,user_id:Number(targetId),until_date:Math.floor(Date.now()/1000)+600,permissions:{can_send_messages:false,can_send_audios:false,can_send_documents:false,can_send_photos:false,can_send_videos:false,can_send_video_notes:false,can_send_voice_notes:false,can_send_polls:false,can_send_other_messages:false,can_add_web_page_previews:false}});await tg(e,"answerCallbackQuery",{callback_query_id:q.id,text:"عضو ۱۰ دقیقه سکوت شد"});return}if(action==="unmute"){await tg(e,"restrictChatMember",{chat_id:id,user_id:Number(targetId),permissions:{can_send_messages:true,can_send_audios:true,can_send_documents:true,can_send_photos:true,can_send_videos:true,can_send_video_notes:true,can_send_voice_notes:true,can_send_polls:true,can_send_other_messages:true,can_add_web_page_previews:true}});await tg(e,"answerCallbackQuery",{callback_query_id:q.id,text:"محدودیت ارسال پیام برداشته شد"});return}if(["confirmban","confirmkick"].includes(action)){await tg(e,"answerCallbackQuery",{callback_query_id:q.id});await tg(e,"editMessageText",{chat_id:chat,message_id:mid,text:action==="confirmban"?"⛔ تأیید نهایی مسدودسازی؟":"🚪 تأیید نهایی اخراج؟",reply_markup:{inline_keyboard:[[{text:"بله، تأیید می‌کنم",callback_data:"um:"+id+":"+targetId+":"+(action==="confirmban"?"doban":"dokick")}],[{text:"لغو",callback_data:"um:"+id+":"+targetId+":back"}]]}});return}if(action==="doban"){await tg(e,"banChatMember",{chat_id:id,user_id:Number(targetId)});await tg(e,"answerCallbackQuery",{callback_query_id:q.id,text:"عضو مسدود شد"});await tg(e,"editMessageText",{chat_id:chat,message_id:mid,text:"⛔ عضو با موفقیت مسدود شد."});return}if(action==="dokick"){await tg(e,"banChatMember",{chat_id:id,user_id:Number(targetId)});await tg(e,"unbanChatMember",{chat_id:id,user_id:Number(targetId),only_if_banned:true});await tg(e,"answerCallbackQuery",{callback_query_id:q.id,text:"عضو اخراج شد"});await tg(e,"editMessageText",{chat_id:chat,message_id:mid,text:"🚪 عضو از گروه اخراج شد."});return}if(action==="ban"||action==="kick"){await tg(e,"answerCallbackQuery",{callback_query_id:q.id});await tg(e,"editMessageText",{chat_id:chat,message_id:mid,text:action==="ban"?"برای مسدودسازی، تأیید نهایی لازم است.":"برای اخراج، تأیید نهایی لازم است.",reply_markup:{inline_keyboard:[[{text:"تأیید نهایی",callback_data:"um:"+id+":"+targetId+":"+(action==="ban"?"confirmban":"confirmkick")}],[{text:"بازگشت",callback_data:"um:"+id+":"+targetId+":back"}]]}});return}await tg(e,"answerCallbackQuery",{callback_query_id:q.id,text:"عملیات نامعتبر"});return}if(d.startsWith("gm:")){const p=d.split(":"),id=p[1],field=p[2];if(!/^-?\d+$/.test(id)||String(chat)!==String(id)){await tg(e,"answerCallbackQuery",{callback_query_id:q.id,text:"درخواست نامعتبر"});return}const member=await tg(e,"getChatMember",{chat_id:id,user_id:q.from.id}).catch(()=>null);if(!member||!["administrator","creator"].includes(member.status)){await tg(e,"answerCallbackQuery",{callback_query_id:q.id,text:"فقط مدیران گروه دسترسی دارند"});return}if(field==="rules"){const x=await group(e,id);await tg(e,"answerCallbackQuery",{callback_query_id:q.id});await tg(e,"sendMessage",{chat_id:chat,text:"📜 قوانین گروه:\n"+x.rules});return}if(field==="stats"){const x=await group(e,id);await tg(e,"answerCallbackQuery",{callback_query_id:q.id});await tg(e,"sendMessage",{chat_id:chat,text:"📊 آمار گروه\nپیام‌ها: "+x.messages+"\nحذف‌ها: "+x.deleted+"\nاخطارها: "+x.warned});return}const fields=["links","spam","welcome","media","forwards","repeat","contentguard"];if(!fields.includes(field)){await tg(e,"answerCallbackQuery",{callback_query_id:q.id,text:"دکمه نامعتبر"});return}const x=await group(e,id);if(field==="links")x.links=!x.links;if(field==="spam")x.antispam=!x.antispam;if(field==="welcome")x.welcome=!x.welcome;if(field==="media")x.media=!x.media;if(field==="forwards")x.forwards=!x.forwards;if(field==="repeat")x.repeatSpam=x.repeatSpam===false;if(field==="contentguard")x.contentGuard=x.contentGuard===false;await sg(e,id,x);await tg(e,"answerCallbackQuery",{callback_query_id:q.id,text:"تنظیم ذخیره شد"});await groupQuickPanel(e,id,chat,mid);return}if(!owner(q.from,e)){await tg(e,"answerCallbackQuery",{callback_query_id:q.id,text:"فقط مدیر ربات دسترسی دارد"});return}
if(d==="stats"){const a=await e.STORE.get("stats:in")||"0",c=await e.STORE.get("stats:groups")||"0";await tg(e,"answerCallbackQuery",{callback_query_id:q.id});await tg(e,"sendMessage",{chat_id:chat,text:"📊 آمار ربات\nپیام‌های دریافتی: "+a+"\nگروه‌های ثبت‌شده: "+c,reply_markup:{inline_keyboard:[[{text:"↩️ بازگشت",callback_data:"home"}]]}});return}
if(d==="features"){await tg(e,"answerCallbackQuery",{callback_query_id:q.id});const text=["✨ قابلیت‌های FXI Bot","━━━━━━━━━━━━━━━━━━━━","","🧰 ابزارهای کاربردی","ماشین‌حساب، تولید رمز، عدد تصادفی، شیر یا خط، تاس، نظرسنجی، تحلیل متن و تبدیل Base64.","","📝 مدیریت شخصی","یادداشت‌ها، فهرست کارها، یادآوری زمان‌دار و دفترچه ذخیره لینک.","","🎮 سرگرمی","بازی حدس عدد و ابزارهای انتخاب تصادفی.","","🛡 مدیریت گروه","قفل لینک و رسانه، ضداسپم، فیلتر پیام تکراری و متن شلوغ، ضد فوروارد، خوشامدگویی و قوانین قابل تنظیم.","","👮 مدیریت اعضا","اخطار، سکوت موقت، رفع سکوت، اخراج و مسدودسازی با پنل دکمه‌ای.","","📚 برای دیدن روش استفاده و نمونه دستورها، راهنمای کامل را باز کن."].join(NL);await tg(e,"sendMessage",{chat_id:chat,text,reply_markup:{inline_keyboard:[[{text:"📚 راهنمای کامل",callback_data:"help"}],[{text:"↩️ بازگشت به پنل",callback_data:"home"}]]}});return}
if(d==="help"){await tg(e,"answerCallbackQuery",{callback_query_id:q.id});await tg(e,"sendMessage",{chat_id:chat,text:help(),reply_markup:{inline_keyboard:[[{text:"✨ قابلیت‌های ربات",callback_data:"features"}],[{text:"↩️ بازگشت به پنل",callback_data:"home"}]]}});return}
if(d==="groups"){const p=await e.STORE.list({prefix:"group:",limit:100}),ids=p.keys.map(x=>x.name.slice(6)).filter(Boolean);await tg(e,"answerCallbackQuery",{callback_query_id:q.id});await tg(e,"sendMessage",{chat_id:chat,text:ids.length?"👥 گروه‌های ثبت‌شده: "+ids.length:"هنوز گروهی ثبت نشده است.",reply_markup:{inline_keyboard:[...ids.slice(0,30).map(id=>[{text:"گروه "+id,callback_data:"g:"+id}]),[{text:"↩️ بازگشت",callback_data:"home"}]]}});return}
if(d.startsWith("g:")){const id=d.slice(2);if(!/^-?\d+$/.test(id)){await tg(e,"answerCallbackQuery",{callback_query_id:q.id,text:"شناسه نامعتبر"});return}const x=await group(e,id);await tg(e,"answerCallbackQuery",{callback_query_id:q.id});await tg(e,"sendMessage",{chat_id:chat,text:["⚙️ تنظیمات گروه "+id,"قفل لینک: "+(x.links?"روشن":"خاموش"),"ضداسپم: "+(x.antispam?"روشن":"خاموش"),"خوشامدگویی: "+(x.welcome?"روشن":"خاموش"),"کلمات ممنوع: "+x.badWords.length].join(NL),reply_markup:{inline_keyboard:[[ {text:x.links?"🔓 بازکردن لینک":"🔒 قفل لینک",callback_data:"gt:"+id+":links"},{text:x.antispam?"ضداسپم خاموش":"ضداسپم روشن",callback_data:"gt:"+id+":spam"}],[{text:x.welcome?"خوشامدگویی خاموش":"خوشامدگویی روشن",callback_data:"gt:"+id+":welcome"}],[{text:x.media?"🔓 بازکردن رسانه":"🖼 قفل رسانه",callback_data:"gt:"+id+":media"},{text:x.forwards?"🔓 آزادسازی فوروارد":"🚫 ضد فوروارد",callback_data:"gt:"+id+":forwards"}],[{text:"📜 ویرایش قوانین",callback_data:"gt:"+id+":edit_rules"},{text:"👋 متن خوشامد",callback_data:"gt:"+id+":edit_welcome"}],[{text:x.repeatSpam===false?"🔁 تکرار پیام روشن":"🔁 تکرار پیام خاموش",callback_data:"gt:"+id+":repeat"},{text:x.contentGuard===false?"🧹 فیلتر متن شلوغ روشن":"🧹 فیلتر متن شلوغ خاموش",callback_data:"gt:"+id+":contentguard"}],[{text:"⏱ تنظیم ضداسپم",callback_data:"gt:"+id+":spamconfig"}],[{text:"⚠️ حد اخطار: "+(x.warnLimit||3),callback_data:"gt:"+id+":warnlimit"},{text:"🛡 مدیریت اعضا",callback_data:"gt:"+id+":moderate"}],[{text:"➕ افزودن کلمه ممنوع",callback_data:"gt:"+id+":add_word"},{text:"➖ حذف کلمه ممنوع",callback_data:"gt:"+id+":del_word"}],[{text:"↩️ فهرست گروه‌ها",callback_data:"groups"}]]}});return}
if(d.startsWith("gt:")){const p=d.split(":");const id=p[1],field=p[2];if(!/^-?\d+$/.test(id)||!["links","spam","welcome","media","forwards","edit_rules","edit_welcome","add_word","del_word","moderate","warnlimit","spamconfig","repeat","contentguard"].includes(field)){await tg(e,"answerCallbackQuery",{callback_query_id:q.id,text:"درخواست نامعتبر"});return}if(field==="repeat"){const x=await group(e,id);x.repeatSpam=x.repeatSpam===false;await sg(e,id,x);await tg(e,"answerCallbackQuery",{callback_query_id:q.id,text:x.repeatSpam?"فیلتر پیام تکراری روشن شد":"فیلتر پیام تکراری خاموش شد"});await tg(e,"sendMessage",{chat_id:chat,text:"🔁 فیلتر پیام تکراری: "+(x.repeatSpam?"روشن":"خاموش")});return}if(field==="contentguard"){const x=await group(e,id);x.contentGuard=x.contentGuard===false;await sg(e,id,x);await tg(e,"answerCallbackQuery",{callback_query_id:q.id,text:x.contentGuard?"فیلتر متن شلوغ روشن شد":"فیلتر متن شلوغ خاموش شد"});await tg(e,"sendMessage",{chat_id:chat,text:"🧹 فیلتر متن شلوغ: "+(x.contentGuard?"روشن":"خاموش")});return}if(field==="spamconfig"){await e.STORE.put("await_group_setting:"+q.from.id,id+"|spamconfig",{expirationTtl:300});await tg(e,"answerCallbackQuery",{callback_query_id:q.id});await tg(e,"sendMessage",{chat_id:chat,text:"تعداد پیام | ثانیه (مثال: ۵ | ۸)"});return}if(field==="warnlimit"){await e.STORE.put("await_group_setting:"+q.from.id,id+"|warnlimit",{expirationTtl:300});await tg(e,"answerCallbackQuery",{callback_query_id:q.id});await tg(e,"sendMessage",{chat_id:chat,text:"حد اخطار را از ۱ تا ۱۰ بفرست."});return}if(field==="moderate"){await e.STORE.put("await_group_moderation:"+q.from.id,id,{expirationTtl:300});await tg(e,"answerCallbackQuery",{callback_query_id:q.id});await tg(e,"sendMessage",{chat_id:chat,text:"🛡 برای مدیریت عضو، این قالب را بفرست:\nشناسه کاربر | عملیات | مدت دقیقه (اختیاری)\nنمونه: 123456789 | mute | 30\nعملیات: mute, unmute, ban, unban, kick"});return}if(field.startsWith("edit_")||field==="add_word"||field==="del_word"){await e.STORE.put("await_group_setting:"+q.from.id,id+"|"+field,{expirationTtl:300});await tg(e,"answerCallbackQuery",{callback_query_id:q.id});await tg(e,"sendMessage",{chat_id:chat,text:field==="edit_rules"?"قوانین جدید گروه را بفرست.":field==="edit_welcome"?"متن خوشامد را بفرست؛ از {name} برای نام کاربر استفاده کن.":field==="add_word"?"کلمه ممنوع را بفرست.":"کلمه‌ای را که باید حذف شود بفرست."});return}const x=await group(e,id);if(field==="links")x.links=!x.links;if(field==="spam")x.antispam=!x.antispam;if(field==="welcome")x.welcome=!x.welcome;if(field==="media")x.media=!x.media;if(field==="forwards")x.forwards=!x.forwards;await sg(e,id,x);await tg(e,"answerCallbackQuery",{callback_query_id:q.id,text:"تنظیم گروه ذخیره شد"});await tg(e,"sendMessage",{chat_id:chat,text:"تنظیمات گروه "+id+" ذخیره شد."});return}
if(d==="home"){await tg(e,"answerCallbackQuery",{callback_query_id:q.id});await tg(e,"editMessageText",{chat_id:chat,message_id:mid,text:panelText(),reply_markup:keyboard()});return}
await tg(e,"answerCallbackQuery",{callback_query_id:q.id})}
