function digits(s){return s.replace(/[۰-۹]/g,d=>String("۰۱۲۳۴۵۶۷۸۹".indexOf(d))).replace(/[٠-٩]/g,d=>String("٠١٢٣٤٥٦٧٨٩".indexOf(d)))}
function calc(s){s=digits(s).replace(/×/g,"*").replace(/÷/g,"/").replace(/,/g,".");if(!/^[\d+\-*/().%\s]+$/.test(s)||s.length>80)throw Error("عبارت نامعتبر است");const t=s.match(/\d+(?:\.\d+)?|[()+\-*/%]/g)||[];if(t.join("")!==s.replace(/\s/g,""))throw Error("فقط محاسبه عددی مجاز است");let i=0;function f(){if(t[i]==="+"){i++;return f()}if(t[i]==="-"){i++;return -f()}if(t[i]==="("){i++;let v=e();if(t[i++]!==")")throw Error("پرانتز ناقص است");return v}let n=t[i++];if(!n||!/^\d/.test(n))throw Error("عبارت ناقص است");return +n}function m(){let v=f();while(["*","/","%"].includes(t[i])){let o=t[i++],r=f();if((o==="/"||o==="%")&&!r)throw Error("تقسیم بر صفر");v=o==="*"?v*r:o==="/"?v/r:v%r}return v}function e(){let v=m();while(t[i]==="+"||t[i]==="-"){let o=t[i++],r=m();v=o==="+"?v+r:v-r}return v}let v=e();if(i!==t.length||!Number.isFinite(v))throw Error("محاسبه ممکن نیست");return +v.toFixed(8)}
