async function kvKeys(e,prefix,limit=1000){let out=[],cursor;do{const r=await e.STORE.list({prefix,limit:Math.min(1000,limit-out.length),cursor});out.push(...r.keys);cursor=r.list_complete?undefined:r.cursor}while(cursor&&out.length<limit);return out}
async function trackMember(e,m){const c=String(m.chat.id),u=m.from||{};if(!u.id||u.is_bot)return;const key="member:"+c+":"+u.id;let old={};try{old=JSON.parse(await e.STORE.get(key)||"{}")}catch{}const value={id:String(u.id),name:[u.first_name,u.last_name].filter(Boolean).join(" ")||"کاربر",username:u.username||"",isBot:!!u.is_bot,messages:(old.messages||0)+1,lastSeen:Date.now()};await e.STORE.put(key,JSON.stringify(value));const info={id:c,title:m.chat.title||old.groupTitle||c,username:m.chat.username||"",type:m.chat.type||"group",lastSeen:Date.now(),active:true};await e.STORE.put("groupinfo:"+c,JSON.stringify(info))}
async function saveEvent(e,type,message,groupId,userId){const id=String(groupId||"");const event={type,message:String(message||"").slice(0,500),groupId:id,userId:userId?String(userId):"",at:Date.now()};await e.STORE.put("event:"+String(event.at).padStart(13,"0")+":"+crypto.randomUUID(),JSON.stringify(event),{expirationTtl:7776000})}
function secureEqual(a,b){a=String(a||"");b=String(b||"");let diff=a.length^b.length,n=Math.max(a.length,b.length);for(let i=0;i<n;i++)diff|=(a.charCodeAt(i)||0)^(b.charCodeAt(i)||0);return diff===0}
