 const out=(data,status=200)=>new Response(JSON.stringify(data),{status,headers});
 if(origin&&origin!==url.origin)return out({ok:false,error:"origin_forbidden"},403);
 if(!e.PANEL_TOKEN||!secureEqual(req.headers.get("Authorization"),"Bearer "+e.PANEL_TOKEN))return out({ok:false,error:"unauthorized"},401);
